argv:
$ErrorActionPreference='Stop'
Add-Type -AssemblyName UIAutomationClient
Add-Type -AssemblyName UIAutomationTypes
Add-Type @"
using System;
using System.Runtime.InteropServices;
public static class W32VerifyPost {
 [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);
}
"@
$edge=Get-Process msedge -ErrorAction SilentlyContinue | Where-Object {$_.MainWindowHandle -ne 0} | Select-Object -First 1
if($null -eq $edge){throw 'Edge not visible'}
[W32VerifyPost]::SetForegroundWindow($edge.MainWindowHandle)|Out-Null
$root=[System.Windows.Automation.AutomationElement]::FromHandle($edge.MainWindowHandle)
$all=$root.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition)
$target=$null
foreach($e in $all){
  $n=[string]$e.Current.Name
  if($n -eq '已發佈查看' -or $n -eq '查看'){
    $target=$e
  }
}
if($null -ne $target){
  try{
    $inv=$target.GetCurrentPattern([System.Windows.Automation.InvokePattern]::Pattern)
    $inv.Invoke()
  }catch{
    try{
      $sel=$target.GetCurrentPattern([System.Windows.Automation.SelectionItemPattern]::Pattern)
      $sel.Select()
    }catch{}
  }
}
Start-Sleep -Seconds 5

$root=[System.Windows.Automation.AutomationElement]::FromHandle($edge.MainWindowHandle)
$all=$root.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition)
$address=''
$hits=@()
foreach($e in $all){
  $ct=$e.Current.ControlType.ProgrammaticName
  $n=[string]$e.Current.Name
  if($ct -eq 'ControlType.Edit' -and [string]$e.Current.AutomationId -eq 'view_1017'){
    try{
      $vp=$e.GetCurrentPattern([System.Windows.Automation.ValuePattern]::Pattern)
      $address=[string]$vp.Current.Value
    }catch{}
  }
  if($n -like '*剛剛真的看著 ChatGPT*' -or $n -like '*你最想把哪件事丟給兩個 AI 一起完成*'){
    $r=$e.Current.BoundingRectangle
    $hits += [pscustomobject]@{type=$ct;name=$n;x=[string]$r.X;y=[string]$r.Y;w=[string]$r.Width;h=[string]$r.Height}
  }
}
[pscustomobject]@{title=$edge.MainWindowTitle;address=$address;post_hits=$hits}|ConvertTo-Json -Depth 6 -Compress
